import configparser
import os
import subprocess
import sys
from pathlib import Path

import pytest

_BACKEND = Path(__file__).resolve().parent.parent
_SKIP_PARTS = {".venv", "venv", "tests", "test", "alembic", "migrations", "node_modules", "__pycache__"}
_CANDIDATES = (
    "app/seed.py", "app/seeds.py", "app/seed_data.py", "app/db/seed.py", "app/database/seed.py",
    "app/scripts/seed.py", "seed.py", "seeds.py", "scripts/seed.py",
)
_MIGRATE = """
import sys
from alembic import command
from alembic.config import Config
cfg = Config("alembic.ini")
cfg.set_main_option("sqlalchemy.url", sys.argv[1].replace("%", "%%"))
command.upgrade(cfg, "head")
"""
# Runs the seed module as the launchers would: its __main__ block when it has one,
# else the first seed function it defines that takes nothing, or only a session.
_SEED = """
import asyncio, importlib, inspect, os, runpy, sys
module, path, url = sys.argv[1], sys.argv[2], sys.argv[3]
sys.path.insert(0, os.getcwd())
source = open(path, encoding="utf-8", errors="replace").read()
if "__name__" in source and "__main__" in source:
    runpy.run_module(module, run_name="__main__", alter_sys=True)
    sys.exit(0)
mod = importlib.import_module(module)
for name in ("main", "seed", "seed_all", "seed_data", "seed_database", "seed_db", "run_seed", "run"):
    fn = getattr(mod, name, None)
    if not callable(fn) or getattr(fn, "__module__", None) != mod.__name__:
        continue
    required = [
        p for p in inspect.signature(fn).parameters.values()
        if p.default is p.empty and p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)
    ]
    if not required:
        result = fn()
        if inspect.iscoroutine(result):
            asyncio.run(result)
        sys.exit(0)
    if len(required) == 1 and required[0].name in ("db", "session", "db_session", "sess", "s"):
        if inspect.iscoroutinefunction(fn):
            continue
        from sqlalchemy import create_engine
        from sqlalchemy.orm import Session
        engine = create_engine(url.replace("+aiosqlite", ""))
        with Session(engine) as session:
            fn(session)
            session.commit()
        sys.exit(0)
print("NO_SEED_ENTRY_POINT")
sys.exit(3)
"""


def _seed_module():
    found = [_BACKEND / c for c in _CANDIDATES if (_BACKEND / c).is_file()]
    if not found:
        found = sorted(
            p for p in _BACKEND.rglob("seed*.py")
            if not _SKIP_PARTS.intersection(p.relative_to(_BACKEND).parts)
        )
    if not found:
        return None
    rel = found[0].relative_to(_BACKEND).with_suffix("")
    return ".".join(rel.parts), found[0]


def _env(url):
    env = dict(os.environ)
    for name in ("dev.env", ".env.example"):
        path = _BACKEND / name
        if path.is_file():
            for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
                line = line.strip()
                if line and not line.startswith("#") and "=" in line:
                    key, value = line.removeprefix("export ").split("=", 1)
                    env.setdefault(key.strip(), value.strip().strip("'").strip('"'))
            break
    env["DATABASE_URL"] = url
    # Seeds print status marks (a check mark, a cross): a console that cannot encode
    # them would crash a seed that works.
    env["PYTHONIOENCODING"] = "utf-8"
    env["PYTHONUTF8"] = "1"
    return env


def _is_async():
    parser = configparser.ConfigParser(interpolation=None)
    try:
        parser.read(_BACKEND / "alembic.ini", encoding="utf-8")
        location = parser.get("alembic", "script_location", fallback="alembic")
    except (configparser.Error, OSError):
        location = "alembic"
    env_py = Path(location.replace("%(here)s", str(_BACKEND)))
    if not env_py.is_absolute():
        env_py = _BACKEND / env_py
    try:
        text = (env_py / "env.py").read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return any(m in text for m in ("async_engine_from_config", "create_async_engine", "AsyncEngine"))


def _run(code, *args, env):
    proc = subprocess.run(
        [sys.executable, "-c", code, *args],
        cwd=_BACKEND, env=env, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=300,
    )
    return proc.returncode, ((proc.stdout or "") + (proc.stderr or ""))[-6000:]

import json
import re
import socket
import time
import urllib.error
import urllib.request

_EMAIL_RE = re.compile(r"""['"]([\w.+-]+@[\w-]+(?:\.[\w-]+)+)['"]""")
_PASSWORD_RE = re.compile(
    r"""(?:password|passwd|pwd|secret)\w*['"]?\s*[:=,(]\s*['"]([^'"\s]{4,64})['"]"""
    r"""|(?:hash_password|get_password_hash|make_password|hashpw|generate_password_hash)\(\s*['"]([^'"\s]{4,64})['"]""",
    re.IGNORECASE,
)
_MAX_SWEEPS = 3
_MAX_CALLS = 160
_SKIP_PATH_RE = re.compile(r"(?i)logout|log-out|signout|delete|reset|admin|webhook|callback|/docs|openapi|redoc")


def _free_port():
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


def _app_target():
    for rel in ("app/main.py", "main.py", "src/main.py", "app/app.py"):
        path = _BACKEND / rel
        if path.is_file() and re.search(r"\b(\w+)\s*=\s*FastAPI\(", path.read_text(encoding="utf-8", errors="replace")):
            name = re.search(r"\b(\w+)\s*=\s*FastAPI\(", path.read_text(encoding="utf-8", errors="replace")).group(1)
            return ".".join(Path(rel).with_suffix("").parts) + ":" + name
    return None


def _call(base, method, path, body=None, token=None, form=False):
    data = None
    headers = {"Accept": "application/json"}
    if body is not None:
        if form:
            from urllib.parse import urlencode
            data = urlencode(body).encode()
            headers["Content-Type"] = "application/x-www-form-urlencoded"
        else:
            data = json.dumps(body).encode()
            headers["Content-Type"] = "application/json"
    if token:
        headers["Authorization"] = "Bearer " + token
    request = urllib.request.Request(base + path, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            raw = response.read().decode("utf-8", "replace")
            status = response.status
    except urllib.error.HTTPError as e:
        raw = e.read().decode("utf-8", "replace")
        status = e.code
    except (urllib.error.URLError, OSError) as e:
        return 599, str(e)
    try:
        return status, json.loads(raw) if raw else None
    except ValueError:
        return status, raw


def _harvest(value, seen):
    """Every scalar under a key, so `{session_id}` and a body's `video_id` can be filled later."""
    if isinstance(value, dict):
        for key, item in value.items():
            if isinstance(item, (str, int)) and not isinstance(item, bool) and str(item):
                seen.setdefault(key, [])
                if item in seen[key]:
                    seen[key].remove(item)
                # What the app returned last wins over the seed's constants.
                seen[key].insert(0, item)
            _harvest(item, seen)
    elif isinstance(value, list):
        for item in value[:20]:
            _harvest(item, seen)


def _resolve(schema, spec, depth=0):
    if not isinstance(schema, dict) or depth > 6:
        return {}
    if "$ref" in schema:
        node = spec
        for part in schema["$ref"].lstrip("#/").split("/"):
            node = node.get(part, {}) if isinstance(node, dict) else {}
        return _resolve(node, spec, depth + 1)
    for key in ("allOf", "anyOf", "oneOf"):
        if key in schema and schema[key]:
            merged = {"properties": {}, "required": []}
            for part in schema[key]:
                part = _resolve(part, spec, depth + 1)
                if part.get("type") == "null":
                    continue
                merged["properties"].update(part.get("properties", {}))
                merged["required"] += part.get("required", [])
                if key != "allOf":
                    merged.update({k: v for k, v in part.items() if k not in ("properties", "required")})
                    break
            return merged
    return schema


def _value_for(name, schema, spec, seen):
    schema = _resolve(schema, spec)
    if name in seen:
        return seen[name][0]
    if "enum" in schema and schema["enum"]:
        return schema["enum"][0]
    if "default" in schema:
        return schema["default"]
    kind = schema.get("type")
    if isinstance(kind, list):
        kind = next((k for k in kind if k != "null"), None)
    if kind == "boolean":
        return True
    if kind in ("integer", "number"):
        return max(1, schema.get("minimum", 1) or 1)
    if kind == "object":
        return _body_for(schema, spec, seen)
    if kind == "array":
        return []
    if "example" in schema:
        return schema["example"]
    if schema.get("format") == "date-time":
        return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    if schema.get("format") == "date":
        return time.strftime("%Y-%m-%d", time.gmtime())
    if re.search(r"(?:^id|_id|_key|_ref|_token|_url|_uri|email)$", name):
        return None  # an id nobody returned: one this walk cannot invent
    return "smoke"


def _body_for(schema, spec, seen):
    schema = _resolve(schema, spec)
    body = {}
    for name in schema.get("required", []):
        value = _value_for(name, schema.get("properties", {}).get(name, {}), spec, seen)
        if value is None:
            return None
        body[name] = value
    return body


def _fill_path(path, seen):
    names = re.findall(r"\{(\w+)\}", path)
    for name in names:
        if name not in seen:
            return None
        path = path.replace("{" + name + "}", str(seen[name][0]))
    return path


def _seed_values():
    """Constants the seed writes, by field name (`video_id="VID-001"`, `{"moment_id": "M-1"}`):
    the ids a user would reach through screens this walk cannot click."""
    import ast
    found = _seed_module()
    seen = {}
    if found is None:
        return seen
    try:
        tree = ast.parse(found[1].read_text(encoding="utf-8", errors="replace"))
    except (OSError, SyntaxError, ValueError):
        return seen

    def keep(name, node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (str, int)) and not isinstance(node.value, bool):
            if str(node.value) and len(str(node.value)) < 120:
                seen.setdefault(name, [])
                if node.value not in seen[name]:
                    seen[name].append(node.value)

    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            for kw in node.keywords:
                if kw.arg:
                    keep(kw.arg, kw.value)
        elif isinstance(node, ast.Dict):
            for key, value in zip(node.keys, node.values):
                if isinstance(key, ast.Constant) and isinstance(key.value, str):
                    keep(key.value, value)
    for secret in ("password", "password_hash", "hashed_password", "email"):
        seen.pop(secret, None)
    return seen


def _db_values(db):
    """Ids and codes the seeded database holds, by column name (`id` also as `<table>_id`)."""
    import sqlite3
    seen = {}
    try:
        con = sqlite3.connect(str(db))
    except sqlite3.Error:
        return seen
    try:
        rows = list(con.execute("SELECT name, sql FROM sqlite_master WHERE type='table'"))
        tables = [r[0] for r in rows if not r[0].startswith(("sqlite_", "alembic"))]
        # The values a CHECK constraint allows are the valid ones for a request field of that name.
        for _name, sql in rows:
            for column, allowed in re.findall(r'"?(\w+)"?\s+IN\s*\(([^)]*)\)', sql or "", re.IGNORECASE):
                for value in re.findall(r"'([^']*)'", allowed):
                    seen.setdefault(column, [])
                    if value not in seen[column]:
                        seen[column].append(value)
        for table in tables:
            columns = [r[1] for r in con.execute('PRAGMA table_info("' + table + '")')]
            for column in columns:
                if not re.search(r"(?:^id|_id|_key|_code|_ref|_status|_type)$", column):
                    continue
                names = [column]
                if column == "id":
                    names = [re.sub(r"(?:ies)$", "y", table).rstrip("s") + "_id", table + "_id"]
                rows = con.execute('SELECT DISTINCT "' + column + '" FROM "' + table + '" WHERE "' + column + '" IS NOT NULL LIMIT 3')
                for (value,) in rows:
                    if isinstance(value, bytes) or value is None:
                        continue
                    for name in names:
                        seen.setdefault(name, [])
                        if value not in seen[name]:
                            seen[name].append(value)
    except sqlite3.Error:
        pass
    finally:
        con.close()
    return seen


def _start_values(db):
    """What a user's first call can use: the seed's constants, then the seeded rows' ids."""
    seen = _seed_values()
    for key, values in _db_values(db).items():
        seen.setdefault(key, [])
        seen[key] = values + [v for v in seen[key] if v not in values]
    return seen


def _personas():
    """(email, [password candidates]) for every account the seed source names."""
    found = _seed_module()
    files = [found[1]] if found else []
    for extra in ("README.md", "../README.md", "dev.env", ".env.example"):
        if (_BACKEND / extra).is_file():
            files.append(_BACKEND / extra)
    emails, passwords = [], []
    for path in files:
        text = path.read_text(encoding="utf-8", errors="replace")
        emails += [e for e in _EMAIL_RE.findall(text) if e not in emails]
        passwords += [p for groups in _PASSWORD_RE.findall(text) for p in groups if p and p not in passwords]
    return emails[:12], passwords[:6]


def _login_routes(spec):
    out = []
    for path, ops in (spec.get("paths") or {}).items():
        if "post" in ops and re.search(r"(?i)(login|token|sign-?in)/?$", path) and "{" not in path:
            out.append(path)
    return sorted(out, key=lambda p: (0 if "login" in p else 1, len(p)))


def _login(base, spec, email, passwords):
    for route in _login_routes(spec):
        for password in passwords:
            for body, form in (({"email": email, "password": password}, False),
                               ({"username": email, "password": password}, False),
                               ({"username": email, "password": password}, True)):
                status, data = _call(base, "POST", route, body, form=form)
                if status < 300 and isinstance(data, dict):
                    token = data.get("access_token") or data.get("token") or (data.get("data") or {}).get("access_token")
                    if isinstance(token, str):
                        return token, data
                if 500 <= status < 599:
                    return None, (route, status, data)
    return None, None


@pytest.fixture(scope="module")
def running_app(tmp_path_factory):
    found = _seed_module()
    target = _app_target()
    if target is None:
        pytest.skip("no FastAPI app object found (app/main.py)")
    db = tmp_path_factory.mktemp("smoke_journey") / "app.db"
    url = ("sqlite+aiosqlite:///" if _is_async() else "sqlite:///") + db.as_posix()
    env = _env(url)
    code, output = _run(_MIGRATE, url, env=env)
    if code != 0:
        pytest.skip("the migrations do not build an empty database; test_pipeline_migration_parity.py reports it")
    if found is not None:
        code, output = _run(_SEED, found[0], str(found[1]), url, env=env)
        if code != 0:
            pytest.skip("the seed does not run; test_pipeline_seed_runs.py reports it")
    port = _free_port()
    # A file, not a pipe: nobody reads a pipe while the walk runs, and a full one blocks the server.
    log_path = db.parent / "uvicorn.log"
    log = open(log_path, "w", encoding="utf-8", errors="replace")
    proc = subprocess.Popen(
        [sys.executable, "-m", "uvicorn", target, "--host", "127.0.0.1", "--port", str(port)],
        cwd=_BACKEND, env=env, stdout=log, stderr=subprocess.STDOUT,
    )
    base = "http://127.0.0.1:" + str(port)
    spec = None
    deadline = time.time() + 60
    while time.time() < deadline and proc.poll() is None:
        status, data = _call(base, "GET", "/openapi.json")
        if status == 200 and isinstance(data, dict):
            spec = data
            break
        time.sleep(0.5)
    if spec is None:
        proc.kill()
        log.close()
        out = log_path.read_text(encoding="utf-8", errors="replace")[-4000:]
        pytest.fail("The app did not start on the migrated, seeded database (uvicorn " + target + "). "
                    "What it printed last:" + chr(10) + out)
    yield base, spec, db
    proc.kill()
    try:
        proc.wait(timeout=10)
    except Exception:
        pass
    log.close()


def _walk(base, spec, token, seen):
    """5xx answers on every GET/POST this walk can fill, a few sweeps deep."""
    failures, called, calls = [], set(), 0
    paths = spec.get("paths") or {}
    for _sweep in range(_MAX_SWEEPS):
        progressed = False
        for path, ops in sorted(paths.items()):
            if _SKIP_PATH_RE.search(path) or path in _login_routes(spec):
                continue
            for method in ("get", "post"):
                op = ops.get(method)
                if op is None or (method, path) in called or calls >= _MAX_CALLS:
                    continue
                filled = _fill_path(path, seen)
                if filled is None:
                    continue
                body = None
                if method == "post":
                    content = ((op.get("requestBody") or {}).get("content") or {}).get("application/json")
                    if content is not None:
                        body = _body_for(content.get("schema") or {}, spec, seen)
                        if body is None:
                            continue
                called.add((method, path))
                calls += 1
                progressed = True
                status, data = _call(base, method.upper(), filled, body, token)
                if status >= 500 and status != 599:
                    failures.append(method.upper() + " " + filled + (" " + json.dumps(body)[:300] if body else "")
                                    + " -> " + str(status) + ": " + str(data)[:300])
                elif status < 300:
                    _harvest(data, seen)
        if not progressed:
            break
    return failures


def test_every_seeded_user_walks_the_api_without_a_server_error(running_app):
    base, spec, db = running_app
    emails, passwords = _personas()
    logins = _login_routes(spec)
    failures = []
    walked = []
    if logins and emails and passwords:
        for email in emails:
            token, data = _login(base, spec, email, passwords)
            if token is None and isinstance(data, tuple):
                failures.append("login as " + email + ": POST " + data[0] + " -> " + str(data[1]) + ": " + str(data[2])[:300])
                continue
            if token is None:
                continue
            seen = _start_values(db)
            _harvest(data, seen)
            walked.append(email)
            failures += ["as " + email + ": " + f for f in _walk(base, spec, token, seen)]
        assert walked or failures, (
            "The app has a login (" + ", ".join(logins) + ") and the seed names accounts ("
            + ", ".join(emails[:5]) + "), but none of them can log in with a password the seed sets. "
            "Every journey needs a seeded login per persona; fix the seed or the login."
        )
    else:
        failures += ["anonymous: " + f for f in _walk(base, spec, None, _start_values(db))]
    assert not failures, (
        "The migrated, seeded app answers 5xx to calls a user makes. Each line is the persona, the "
        "call (filled from earlier responses) and the answer - fix the route, service, seed or "
        "migration behind it:" + chr(10) + chr(10).join(failures[:25])
    )
